public class GridAnalyzer {
    private Document document;
    public GridAnalyzer(Document document) {
        this.document = document;
    }
    public List<List<String>> gridScan() {
        List<List<String>> output = new ArrayList<>();
         Element primarySection = document.selectFirst("div#maincontent");
        if (primarySection == null) {
            return output;
        }
        Element grid = primarySection.selectFirst("table");
        if (grid == null) {
            return output;
        }
        for (Element tableRow : grid.select("tr")) {
            Elements headerCells = tableRow.select("th");
            if (!headerCells.isEmpty()) {
                continue;
            }


            List<String> line = new ArrayList<>();
            for (Element cell : tableRow.select("td")) {
                line.add(cell.text());
            }
            output.add(line);
        }
        return output;
    }
}

public class DataProcessor {
    private List<List<String>> inputData;
    private Map<String, List<Object>> connections;

    public DataProcessor(List<List<String>> inputData) {
        this.inputData = inputData;
        this.connections = new HashMap<>();
    }

    public void process() {
        for (List<String> line : inputData) {
            if (line.size() != 5) continue;
            String node = line.get(0);
            String address = line.get(1);
            try {
                float linkQuality = Float.parseFloat(line.get(2));
                float neighborLinkQuality = Float.parseFloat(line.get(3));
                float etxValue = Float.parseFloat(line.get(4));

                List<Object> entries = new ArrayList<>();
                entries.add(address);
                entries.add(linkQuality);
                entries.add(neighborLinkQuality);
                entries.add(etxValue);

                connections.put(node, entries);
            } catch (NumberFormatException ex) {

                ex.printStackTrace();
            }
        }
    }

    public Map<String, List<Object>> getConnections() {
        return connections;
    }
}

