public class ImageScaler {
    private static final int TARGET_SIZE = 800;
    public static BufferedImage scale(BufferedImage image) {
        int width = image.getWidth();
        int height = image.getHeight();
        if (width > TARGET_SIZE) {
            double ratio = (double) TARGET_SIZE / width;
            int scaledHeight = (int) Math.floor(height * ratio);

            Image temp = image.getScaledInstance(TARGET_SIZE, scaledHeight, Image.SCALE_AREA_AVERAGING);
            BufferedImage scaled = new BufferedImage(TARGET_SIZE, scaledHeight, image.getType());
            Graphics2D graphics = scaled.createGraphics();
            graphics.drawImage(temp, 0, 0, null);
            graphics.dispose();

            return scaled;
        }
        return image;
    }
}

