public class AttributeSelector {

    public static class Outcome {
        public double[][] XChosen;
        public boolean[] filter;

        public Outcome(double[][] XChosen, boolean[] filter) {
            this.XChosen = XChosen;
            this.filter = filter;
        }
    }

    public static Outcome attributeSelectionVariance(double[][] X, double limit) {
        int sampleCount = X.length;
        int attributeCount = X[0].length;

        boolean[] filter = new boolean[attributeCount];
        int chosenCount = 0;

        for (int j = 0; j < attributeCount; j++) {
            double average = 0;
            for (int i = 0; i < sampleCount; i++) {
                average += X[i][j];
            }
            average /= sampleCount;

            double variance = 0;
            for (int i = 0; i < sampleCount; i++) {
                variance += (X[i][j] - average) * (X[i][j] - average);
            }
            variance /= sampleCount;

            if (variance > limit) {
                filter[j] = true;
                chosenCount++;
            } else {
                filter[j] = false;
            }
        }

        double[][] XChosen = new double[sampleCount][chosenCount];
        for (int i = 0; i < sampleCount; i++) {
            int columnIndex = 0;
            for (int j = 0; j < attributeCount; j++) {
                if (filter[j]) {
                    XChosen[i][columnIndex++] = X[i][j];
                }
            }
        }

        return new Outcome(XChosen, filter);
    }
}

