public class BasicCounter {

    public Map<String, Object> iterateEntries() {
        return new HashMap<>();
    }

    public Map<String, Object> asDictionary(String retrieveValue) {
        Map<String, Object> output = new HashMap<>();

        for (Map.Entry<String, Object> entry : iterateEntries().entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof BasicCounter) {
                if (retrieveValue != null) {
                    try {
                        value = value.getClass().getField(retrieveValue).get(value);
                    } catch (Exception ex) {
                        ex.printStackTrace();
                        value = null;
                    }
                }
                output.put(key, value);
            } else if (value instanceof BasicCounter) {
                output.put(key, ((BasicCounter) value).asDictionary(retrieveValue));
            } else {
                output.put(key, value);
            }
        }

        return output;
    }
}

