public class TriangleMaximumRoute {

    private int[][] matrix;
    private int[][] cache;
    private static final int UNDEFINED = Integer.MIN_VALUE;

    public TriangleMaximumRoute(int[][] matrix) {
        this.matrix = matrix;
        this.cache = new int[matrix.length][matrix[0].length];
        for (int row = 0; row < cache.length; row++) {
            for (int col = 0; col < cache[row].length; col++) {
                cache[row][col] = UNDEFINED;
            }
        }
    }

    public int maximumRouteSum() {
        return traverse(0, 0);
    }

    private int traverse(int row, int col) {
        if (row == matrix.length) {
            return 0;
        }

        if (cache[row][col] == UNDEFINED) {
            cache[row][col] = matrix[row][col] + Math.max(traverse(row + 1, col), traverse(row + 1, col + 1));
        }

        return cache[row][col];
    }
}

public class ColorPerturbation {

    public static Mat korniaColorPerturbation(Mat image, float parameter) {
        if (parameter * 255 > 1) {
            Mat perturbed = image.clone();

            double alpha = 1.0;
            double beta = (Math.random() * 2 - 1) * parameter * 255;
            perturbed.convertTo(perturbed, -1, alpha, beta);

            Mat hsv = new Mat();
            Imgproc.cvtColor(perturbed, hsv, Imgproc.COLOR_RGB2HSV);

            List<Mat> hsvChannels = new ArrayList<>();
            Core.split(hsv, hsvChannels);
            hsvChannels.get(1).convertTo(hsvChannels.get(1), -1, 1, (Math.random() * 2 - 1) * parameter * 255);
            Core.merge(hsvChannels, hsv);

            Imgproc.cvtColor(hsv, perturbed, Imgproc.COLOR_HSV2RGB);

            return perturbed;
        }
        return image;
    }
}

