public class ForegroundExchangeTest {

    @Test
    public void testFgExchangeQuick() {
        int batchSize = 2;
        int imgHeight = 5;
        int imgWidth = 5;
        int channelCount = 3;
        Random random = new Random();

        Mat[] backgroundData = new Mat[batchSize];
        for (int batchIdx = 0; batchIdx < batchSize; batchIdx++) {
            backgroundData[batchIdx] = new Mat(imgHeight, imgWidth, CvType.CV_32FC3);
            for (int row = 0; row < imgHeight; row++) {
                for (int col = 0; col < imgWidth; col++) {
                    double[] values = new double[channelCount];
                    for (int chan = 0; chan < channelCount; chan++) {
                        values[chan] = -1.0;
                    }
                    backgroundData[batchIdx].put(row, col, values);
                }
            }
        }

        double[] backgroundLabels = new double[batchSize];
        for (int batchIdx = 0; batchIdx < batchSize; batchIdx++) {
            backgroundLabels[batchIdx] = random.nextDouble();
        }

        Mat foreground = new Mat(imgHeight, imgWidth, CvType.CV_32F);
        for (int row = 0; row < imgHeight; row++) {
            for (int col = 0; col < imgWidth; col++) {
                foreground.put(row, col, 0.5 + 0.1 * random.nextGaussian());
            }
        }

        InMemoryDataset backgroundSet = new InMemoryDataset(backgroundData, backgroundLabels);
        ForegroundExchange fgExchange = new ForegroundExchange(backgroundSet, new int[]{5, 5}, null);

        Mat exchanged = fgExchange.apply(foreground);
        Mat exchangedSingleChannel = new Mat();
        Core.extractChannel(exchanged, exchangedSingleChannel, 0);

        for (int row = 0; row < imgHeight; row++) {
            for (int col = 0; col < imgWidth; col++) {
                double valExchanged = exchangedSingleChannel.get(row, col)[0];
                double valForeground = foreground.get(row, col)[0];
                assertEquals(valExchanged <= -1, valForeground <= 0.5);
            }
        }
    }
}

