public class SerialPeripheral {

    private OutputStream stream;

    public SerialPeripheral(OutputStream stream) {
        this.stream = stream;
    }

    public void send(int command, long paramA, long paramB) throws IOException {
        ByteBuffer buffer = ByteBuffer.allocate(8); // 两个 4 字节的无符号长整型
        buffer.order(ByteOrder.LITTLE_ENDIAN);
        buffer.putInt((int) paramA);
        buffer.putInt((int) paramB);

        stream.write(new byte[] { (byte) command });
        stream.write(buffer.array());
        stream.flush();
    }
}

public class SerialPeripheral {

    private InputStream stream;

    public SerialPeripheral(InputStream stream) {
        this.stream = stream;
    }

    public long storageInit() throws IOException {
        send(0x03, 0, 0);

        byte[] buffer = new byte[4];
        int bytesRead = stream.read(buffer);
        if (bytesRead != 4) {
            throw new IOException("Failed to read 4 bytes from serial");
        }

        ByteBuffer bb = ByteBuffer.wrap(buffer);
        bb.order(ByteOrder.LITTLE_ENDIAN);
        return bb.getInt() & 0xFFFFFFFFL;
    }
}

