public class FunctionHolder {

    private List<Object> defaultsW;

    public Object fgetFunctionDefaults(Space sp) {
        if (defaultsW == null || defaultsW.isEmpty()) {
            return sp.wNone();
        }
        return sp.newTuple(defaultsW);
    }
}

public class FuncWrapper {

    private Object wUnit;
    private Object wFuncState;

    public Object fgetContext(Space gap) {
        if (wUnit == null) {
            if (wFuncState != null && !gap.hasW(wFuncState, gap.wNone())) {
                wUnit = gap.invokeMethod(wFuncState, "get", gap.bind("__name__"));
            } else {
                wUnit = gap.wNone();
            }
        }
        return wUnit;
    }
}

public class FunctionHolder {

    public static Object descrMethod__new__(Space sp, Class<?> wKind, Object wCallable, Object wObject, Object wType) {
        if (sp.isW(wObject, sp.wNone())) {
            wObject = null;
        }
        Method method = sp.allocateInstance(Method.class, wKind);
        method.init(sp, wCallable, wObject, wType);
        return sp.wrap(method);
    }
}

public class MethodContainer {

    private Object wFunction;
    private Object wInstance;
    private Space space;

    public Object descrMethodHash() {
        Object wResult = space.hash(wFunction);
        if (wInstance != null) {
            wResult = space.xor(wResult, space.hash(wInstance));
        }
        return wResult;
    }
}

public Object descrClassMethodGet(Space space, Object wObj, Object wKlass) {
        if (space.isW(wKlass, space.wNone())) {
            wKlass = space.type(wObj);
        }
        return space.wrap(new Method(space, wFunction, wKlass, space.wNone()));
    }

public class NativeCallableHolder {

    public static Object explainBuiltinFunctionCreate(Area area, Class<?> wKind, Object wCallable) {
        Function call = area.interpW(Function.class, wCallable);
        BuiltinFunction nativeFn = area.allocateInstance(BuiltinFunction.class, wKind);
        nativeFn.init(call);
        return area.wrap(nativeFn);
    }
}

public class Benchmark {

