public boolean hasUpperBoundSealed() {
    if (highCut.node == null) {
        throw new IllegalArgumentException("Range unbounded above");
    } else {
        return !highCut.under;
    }
}

public boolean hasLowerBoundSealed() {
    if (lowCut.node == null) {
        throw new IllegalArgumentException("Range unbounded below");
    } else {
        return lowCut.under;
    }
}

public boolean contains(Range peer) {
    if (peer == null) {
        throw new IllegalArgumentException("Range required");
    }
    return (this.lowCut.compareTo(peer.lowCut) <= 0) &&
           (this.highCut.compareTo(peer.highCut) >= 0);
}

