public class ReplyReader {

    private static final Logger tracer =
            Logger.getLogger(ReplyReader.class.getName());

    public void readReply(Response reply) throws IOException {
        tracer.info("Saving file to download path: " + Settings.DOWNLOAD_PATH);

        try (InputStream dataStream = reply.getRawStream();
             FileOutputStream fileStream = new FileOutputStream(Settings.DOWNLOAD_PATH)) {

            byte[] chunk = new byte[1024];
            int bytesCount;
            while ((bytesCount = dataStream.read(chunk)) != -1) {
                fileStream.write(chunk, 0, bytesCount);
            }
        }

        tracer.info("File saved successfully");
    }
}

public List<Map<String, Object>> sendFeatures(List<Object> features) {
    List<List<Object>> boxList = this.boxHead.getBboxes(features);
    List<Map<String, Object>> boxResults = new ArrayList<>();

    for (List<Object> boxItem : boxList) {
        List<Object> detBoxes = (List<Object>) boxItem.get(0);
        List<Integer> detTags = (List<Integer>) boxItem.get(1);
        Map<String, Object> result =
                box2map(detBoxes, detTags, this.boxHead.getNumClasses());
        boxResults.add(result);
    }

    return boxResults.isEmpty()
            ? new ArrayList<>()
            : Arrays.asList(boxResults.get(0));
}

