public class HttpUtils {

    public static Integer getStatusCode(String host, String path) {
        if (path == null) {
            path = "/";
        }
        try {
            URL url = new URL("http://" + host + path);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("HEAD");
            conn.connect();
            return conn.getResponseCode();
        } catch (Exception e) {
            return null;
        }
    }
}

public static void waitReady(String host, String path) {
    if (path == null) path = "/";
    while (fetchStatusCode(host, path) != 200) {
        try {
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

