public class CalendarUtils {

    public static long[] fetchCalendar(TradingCalendar tradingSchedule, BarReader source) {
        long[] allTicks = tradingSchedule.getAllMinutes();
        int begin = locateSorted(allTicks, source.getFirstTradingDay(), false);
        int finish = locateSorted(allTicks, source.getLastAvailableDt(), true);
        return Arrays.copyOfRange(allTicks, begin, finish);
    }

    private static int locateSorted(long[] values, long target, boolean rightSide) {
        int left = 0;
        int right = values.length;
        while (left < right) {
            int pivot = (left + right) >>> 1;
            if (values[pivot] < target || (rightSide && values[pivot] == target)) {
                left = pivot + 1;
            } else {
                right = pivot;
            }
        }
        return left;
    }
}

