public void onComplete() {
    if (this.confPath != null && new File(this.confPath).exists()) {
        if (this.execAsUser) {
            try {
                ProcessBuilder pb = new ProcessBuilder("sudo", "rm", this.confPath);
                pb.inheritIO();
                Process proc = pb.start();
                proc.waitFor();
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        } else {
            new File(this.confPath).delete();
        }
    }
    if (this.errorStream != null) {
        try {
            this.errorStream.close();
        } catch (FileNotFoundException e) {

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

