public class TimeFormatter {

    public static String fetchDateRendered(ZonedDateTime ts, boolean isFullDay) {
        if (isFullDay) {
            return ts.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
        } else {
            return ts.format(
                DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSSZ")
            );
        }
    }
}

public class ImageUtils {

    public static int getImageIdFromFileName(String filename, int idIter) {

        String nameWithoutExt = filename.contains(".") 
            ? filename.substring(0, filename.lastIndexOf('.')) 
            : filename;

        if (nameWithoutExt.matches("\\d+")) {  
            return Integer.parseInt(nameWithoutExt);
        }

        return idIter;
    }
}

public class LabelParser {

    public static List<List<Integer>> labelParser(List<String> labelsStr) {
        List<List<Integer>> labels = new ArrayList<>();

        for (String labelStr : labelsStr) {
            String[] parts = labelStr.trim().split(",");
            List<Integer> label = new ArrayList<>();
            for (String item : parts) {
                label.add(Integer.parseInt(item));
            }
            labels.add(label);
        }

        return labels;
    }
}

