public Object applyMarginMode(String marginKind, String symbol, Map<String, Object> params) throws Exception {
    marginKind = marginKind.toUpperCase();
    if (!marginKind.equals("ISOLATED") && !marginKind.equals("CROSSED")) {
        throw new BadRequest(this.id + " marginType must be either isolated or crossed");
    }

    this.loadMarkets();
    Map<String, Object> market = this.market(symbol);
    String endpoint = null;

    if ((boolean) market.get("linear")) {
        endpoint = "fapiPrivatePostMarginType";
    } else if ((boolean) market.get("inverse")) {
        endpoint = "dapiPrivatePostMarginType";
    } else {
        throw new NotSupported(this.id + " setMarginMode() supports linear and inverse contracts only");
    }

    Map<String, Object> payload = new HashMap<>();
    payload.put("symbol", market.get("id"));
    payload.put("marginType", marginKind);

    Map<String, Object> mergedPayload = this.extend(payload, params);

    return this.invokeMethodByName(endpoint, mergedPayload);
}

